pub fn set_at(a: &mut Vec<i32>, i: usize, val: i32) {
    // Mutate in place without changing length.
    if let Some(slot) = a.get_mut(i) {
        *slot = val;
    } else {
        // Out-of-bounds is not expected under the stated assumptions.
        panic!("index out of bounds");
    }
}

pub fn myfun(a: &mut Vec<i32>, sum: &mut Vec<i32>, n: i32) {
    // Assumptions (as per problem statement):
    // - n > 0 and n < 1000
    // - a.len() == n as usize
    // - sum.len() == 1
    assert!(n > 0 && n < 1000);
    assert_eq!(a.len(), n as usize);
    assert_eq!(sum.len(), 1);

    let val = n + 1;
    for idx in 0..a.len() {
        set_at(a, idx, val);
    }

    // Ensure lengths remain unchanged.
    debug_assert_eq!(a.len(), n as usize);
    debug_assert_eq!(sum.len(), 1);
}